NEW_FILES = json.loads(r"""{"apps/api/src/checkout/checkout-phone-policy.ts": "f8973cae0b6c14a58c19f31f28dd32b373c8867b", "apps/api/src/checkout/checkout-phone.controller.ts": "f68ce9008390efeba0c2034edb43bccdf5dd216c", "apps/api/src/checkout/checkout-phone.service.ts": "c36eb05c053101169f0553e7e3ea17865bdfc507", "apps/api/src/checkout/msg91-checkout-otp.provider.ts": "65b3c5ef5c4c6248809cb73ffa09d7c0df885850", "apps/web/components/checkout-phone-verification.module.css": "1bd0d3bcb7054a7bbde42b894368568b8035aaa6", "apps/web/components/checkout-phone-verification.tsx": "4125963e6ca1c1ee7b77cbafb0956d1667380a3e", "apps/web/lib/checkout-phone.ts": "0adb31a512a0e150ce03a01807fbdeaaefc09594", "deploy/sql/checkout-phone-retention.sql": "1ef5875b8096f714ee43c4924c1d680535a0c263", "deploy/sql/checkout-phone-verification.sql": "13dae3aa769c98ca87167ad990e14b1c38042384", "docs/guest-checkout-phone-verification.md": "fd3531578f26afd3a908378f85fc6ec48279a21b", "tests/checkout-phone-contracts.test.cjs": "501cb4c515e401d673fa0b8af1d37020f32a5c78", "tests/checkout-phone-input.test.cjs": "68c980235703587f49eb2b31723140c640b1c2a6", "tests/checkout-phone.browser.mjs": "45a5c13d459eddbeaa412aa95a093df364641fc5", "tests/checkout-phone.test.ts": "2e11dcb411b12d56e6beb165d5c04df0aeb2f5a2"}""")

def blob(data):
    return hashlib.sha1(b"blob " + str(len(data)).encode() + b"\0" + data).hexdigest()

pending = {}
for name, spec in MANIFEST.items():
    source = Path(name).read_bytes()
    if blob(source) != spec["before"]:
        raise SystemExit("Source changed; refusing to overwrite " + name)
    lines = source.decode("utf-8").splitlines(keepends=True)
    for start, end, content in reversed(spec["edits"]):
        lines[start:end] = [content]
    result = "".join(lines).encode("utf-8")
    if blob(result) != spec["after"]:
        raise SystemExit("Patch does not match expected result: " + name)
    pending[name] = result
for name, expected in NEW_FILES.items():
    if blob(Path(name).read_bytes()) != expected:
        raise SystemExit("New source content mismatch: " + name)
for name, data in pending.items():
    Path(name).write_bytes(data)
print("Integrated eight existing files and verified fourteen new files. Ready for full PR CI.")
